(() => {
  'use strict';
  const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
  const UI={title:document.querySelector('#titleScreen'),start:document.querySelector('#startButton'),dialogue:document.querySelector('#dialogue'),speaker:document.querySelector('#speaker'),text:document.querySelector('#dialogueText'),portrait:document.querySelector('#portrait'),label:document.querySelector('#areaLabel'),prompt:document.querySelector('#prompt'),balls:document.querySelector('#ballCount'),plural:document.querySelector('#ballPlural'),objective:document.querySelector('#objective'),map:document.querySelector('#worldMap'),mapButton:document.querySelector('#mapButton'),closeMap:document.querySelector('#closeMap'),cream:document.querySelector('#creamBadge')};
  const T=32,W=20,H=15;
  const state={scene:'bulbo',x:10,y:10,dir:'down',keys:{},dialogue:null,started:false,playerName:'Bulbo',balls:0,items:{worldMap:false,dayCream:0},relations:{jason:0},flags:{metMritto:false,gotMap:false,metJason:false,gotCream:false},step:0};
  const C={grass:'#66c86f',grass2:'#59b963',path:'#f6d990',wall:'#3c2a54',floor:'#e8b883',water:'#54bed1',dark:'#201832'};
  const maps={
    bulbo:{name:'MAISON DE BULBO',type:'inside',spawn:[10,10],doors:[{x:10,y:13,to:'village',tx:5,ty:5}],blocks:[[0,0,20,2],[0,0,2,15],[18,0,2,15],[0,14,20,1],[3,4,5,3],[13,3,4,3]],npcs:[{x:9,y:5,name:'Sexyflex',kind:'sexyflex',lines:[['Sexyflex','Zzz… Chaque muscle est parfaitement détendu. C’est une discipline.'],['Bulbo','Sexyflex dort debout. Enfin… presque.']]}]},
    village:{name:'BITCH CITY',type:'outside',spawn:[5,5],doors:[{x:5,y:4,to:'bulbo',tx:10,ty:12},{x:14,y:4,to:'duo',tx:10,ty:12},{x:10,y:8,to:'slayhouse',tx:10,ty:12},{x:10,y:14,to:'route28',tx:10,ty:1}],blocks:[[0,0,20,1],[0,0,1,15],[19,0,1,15],[2,1,6,4],[12,1,6,4],[6,7,8,2],[2,10,6,4],[12,10,6,4]],npcs:[{x:16,y:7,name:'Pancarte',kind:'sign',lines:[['Pancarte','→ Slayhouse : soins, Slayboules et ragots frais.']]},{x:8,y:13,name:'Panneau',kind:'sign',lines:[['Panneau','Route 28 — Petite ville de Lefilip. Oui, vingt-huit. Ne pose pas de question.']]}]},
    duo:{name:'CHEZ MRITTO & FRAT',type:'inside',spawn:[10,12],doors:[{x:10,y:13,to:'village',tx:14,ty:5}],blocks:[[0,0,20,2],[0,0,2,15],[18,0,2,15],[0,14,20,1],[3,3,5,3],[12,3,5,3]],npcs:[{x:7,y:8,name:'Mritto',kind:'mritto',action:'mrittoGift',lines:[['Mritto','Hey giiiiirl !'],['Mritto','Enfin te voilà… notre ville manque cruellement de vilaines. 😉'],['Mritto','Prends ces 10 Slayboules. Avec ça, tu pourras capturer des Slays sauvages dès que les Slaymatchs commenceront.'],['Système','Tu reçois 10 Slayboules !']]},{x:12,y:8,name:'Fratmentali',kind:'frat',action:'mapGift',lines:[['Fratmentali','Avant que tu partes, prends cette carte d’Hackénia. Elle est ancienne : Bitch City y porte encore le nom d’Emak.'],['Fratmentali','La Route 28 mène à Talentia, la ville de Lefilip. Plus loin, tu trouveras Pariche.'],['Système','Fratmentali te donne la Carte d’Hackénia !']]},{x:6,y:5,name:'Nocturnyx',kind:'nocturnyx',lines:[['Mritto','Voici Nocturnyx : type Obscur, confiance maximale, épaules homologuées.']]},{x:13,y:5,name:'Veloursa',kind:'veloursa',lines:[['Fratmentali','Veloursa est de type Mental. Elle sait exactement ce que tu penses de sa tenue.']]}]},
    slayhouse:{name:'SLAYHOUSE',type:'inside',spawn:[10,12],doors:[{x:10,y:13,to:'village',tx:10,ty:9}],blocks:[[0,0,20,2],[0,0,2,15],[18,0,2,15],[0,14,20,1],[3,3,14,3],[4,8,3,2],[13,8,3,2]],npcs:[{x:10,y:6,name:'Nicki Doll',kind:'nicki',lines:[['Nicki Doll','Bienvenue dans ma Slayhouse, ma chérie. Soins, boutique et conseils de runway : tout est LE-GEN-DAIRE !'],['Nicki Doll','Je viens de Pariche, la grande ville située après la petite ville de Lefilip. Là-bas, un trottoir peut devenir un podium en trois secondes.'],['Nicki Doll','Prends soin de tes Slays, travaille leurs attaques autant que leur démarche… et surtout, ne merde pas.']]}]},
    route28:{name:'ROUTE 28',type:'route',spawn:[10,1],doors:[{x:10,y:0,to:'village',tx:10,ty:13}],blocks:[[0,0,9,1],[11,0,9,1],[0,0,1,15],[19,0,1,15],[2,3,5,3],[13,2,5,4],[2,10,6,3],[12,10,6,3]],npcs:[{x:10,y:8,name:'Homme curieux',kind:'jason',action:'jason',lines:[['Homme curieux','Alors c’est ça, Bitch City ? J’habite à Talentia, juste à côté. J’en avais tellement entendu parler que je voulais voir ça de mes propres yeux.'],['Homme curieux','C’est encore petit… mais il y a quelque chose ici. Je repasserai.']]},{x:10,y:13,name:'À suivre',kind:'sign',lines:[['À suivre','La Route 28 continue vers Talentia…']] }]}
  };
  // Points d’extension prévus pour les prochaines versions.
  const SlaySystems={types:['Eau','Feu','Plante','Glace','Foudre','Vent','Obscur','Clair','Mental','Fantôme'],battle:null,capture:null,runway:null,items:{dayCream:{heal:20,radiantDays:1}},social:{romanceableNpcs:['jason'],partnerChoice:null,homeCompanion:null}};
  window.SlayGame={state,maps,systems:SlaySystems};
  function collide(x,y){const m=maps[state.scene];if(x<0||y<0||x>=W||y>=H)return true;return m.blocks.some(([bx,by,bw,bh])=>x>=bx&&x<bx+bw&&y>=by&&y<by+bh)||m.npcs.some(n=>n.x===x&&n.y===y);}
  function move(dx,dy,dir){if(!state.started||state.dialogue||!UI.map.hidden)return;state.dir=dir;const nx=state.x+dx,ny=state.y+dy;const door=maps[state.scene].doors.find(d=>d.x===nx&&d.y===ny);if(door){changeScene(door.to,door.tx,door.ty);return}if(!collide(nx,ny)){state.x=nx;state.y=ny}draw();}
  function changeScene(scene,x,y){state.scene=scene;state.x=x;state.y=y;showLabel(scene==='bulbo'?'MAISON DE '+state.playerName.toUpperCase():maps[scene].name);if(scene==='village')setObjective(state.flags.metMritto?'Rejoindre la Route 28':'Rendre visite à Mritto et Fratmentali');if(scene==='route28')setObjective('Rejoindre Talentia et trouver Lefilip (à suivre)');draw();}
  function showLabel(t){UI.label.textContent=t;UI.label.classList.add('show');clearTimeout(showLabel.t);showLabel.t=setTimeout(()=>UI.label.classList.remove('show'),1700)}
  function setObjective(t){UI.objective.textContent='Objectif : '+t}
  function target(){const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[state.dir];return[state.x+d[0],state.y+d[1]]}
  function nearby(){const [x,y]=target();return maps[state.scene].npcs.find(n=>n.x===x&&n.y===y)}
  function interact(){if(!state.started)return;if(state.dialogue){advanceDialogue();return}const n=nearby();if(n)openDialogue(n)}
  function openDialogue(n){let lines=n.lines;if(n.action==='mrittoGift'&&state.flags.metMritto)lines=[['Mritto','Dix Slayboules, une ville pleine de potentiel et toi au milieu… Fais-moi quelque chose de fabuleux, giiiiirl.']];if(n.action==='mapGift'&&state.flags.gotMap)lines=[['Fratmentali','Consulte la carte quand tu veux. Bitch City est au sud, à l’ancien emplacement d’Emak.']];if(n.action==='jason'&&state.flags.metJason&&!state.flags.gotCream)lines=[['Jason','Au fait, moi c’est Jason. Et toi… tu es encore plus intéressant de près.'],['Jason','Tiens, une Crème de jour. Elle rend 20 PV à un Slay, ou te donne un teint radieux pendant une journée. Je ne dis pas que tu en as besoin.'],['Système','Jason te donne une Crème de jour !']];else if(n.action==='jason'&&state.flags.gotCream)lines=[['Jason','Ce teint te va bien. Talentia n’est plus très loin… on pourrait s’y recroiser.']];state.dialogue={n,lines,i:0};showLine()}
  function showLine(){const [speaker,text]=state.dialogue.lines[state.dialogue.i];UI.speaker.textContent=speaker==='Bulbo'?state.playerName:speaker;UI.text.textContent=text.replaceAll('Bulbo',state.playerName);UI.portrait.style.background=portraitColor(state.dialogue.n.kind);UI.dialogue.hidden=false;UI.prompt.classList.remove('show')}
  function advanceDialogue(){const d=state.dialogue;if(d.i<d.lines.length-1){d.i++;showLine();return}if(d.n.action==='mrittoGift'&&!state.flags.metMritto){state.flags.metMritto=true;state.balls=10;UI.balls.textContent='10';UI.plural.textContent='s';setObjective('Récupérer la carte auprès de Fratmentali')}if(d.n.action==='mapGift'&&!state.flags.gotMap){state.flags.gotMap=true;state.items.worldMap=true;UI.mapButton.hidden=false;setObjective('Prendre la sortie vers la Route 28')}if(d.n.action==='jason'&&!state.flags.metJason){state.flags.metJason=true;state.relations.jason=1}else if(d.n.action==='jason'&&!state.flags.gotCream){state.flags.gotCream=true;state.items.dayCream=1;state.relations.jason=2;UI.cream.hidden=false}state.dialogue=null;UI.dialogue.hidden=true;draw()}
  function portraitColor(k){return({mritto:'#5f3d9d',frat:'#e85aa9',nicki:'#f43ea5',jason:'#347da0',sexyflex:'#ef884f',nocturnyx:'#382d62',veloursa:'#f08bc2',healer:'#43cbd0',shop:'#f4bd4b',sign:'#99815b'}[k]||'#69c474')}
  function tile(x,y,color){ctx.fillStyle=color;ctx.fillRect(x*T,y*T,T,T)}
  function flower(x,y,c){ctx.fillStyle='#fff';ctx.fillRect(x+12,y+9,4,4);ctx.fillStyle=c;ctx.fillRect(x+8,y+9,4,4);ctx.fillRect(x+16,y+9,4,4);ctx.fillRect(x+12,y+5,4,4);ctx.fillRect(x+12,y+13,4,4);ctx.fillStyle='#3b9b56';ctx.fillRect(x+13,y+17,2,8)}
  function draw(){const m=maps[state.scene];ctx.clearRect(0,0,640,480);if(m.type==='outside'||m.type==='route')drawOutside(m);else drawInside(m);m.npcs.forEach(drawNpc);drawPlayer();const n=nearby();UI.prompt.classList.toggle('show',!!n&&!state.dialogue);}
  function drawOutside(m){for(let y=0;y<H;y++)for(let x=0;x<W;x++){tile(x,y,(x+y)%2?C.grass:C.grass2);if((x*11+y*7)%17===0){ctx.fillStyle='#87d783';ctx.fillRect(x*T+5,y*T+6,4,7)}}ctx.fillStyle=C.path;if(state.scene==='village'){ctx.fillRect(9*T,0,2*T,15*T);ctx.fillRect(0,5*T,20*T,2*T);ctx.fillRect(9*T,9*T,2*T,5*T);drawHouse(2,1,6,4,'#ef779f',state.playerName.toUpperCase());drawHouse(12,1,6,4,'#8f74d8','MRITTO + FRAT');drawHouse(2,10,6,4,'#79a0b2','À LOUER');drawHouse(12,10,6,4,'#79a0b2','À LOUER');drawHouse(6,7,8,2,'#ff65b4','SLAYHOUSE');for(let x=0;x<20;x++)if(x<8||x>11)flower(x*T,7*T,['#ff4b94','#ffe45e','#63dded','#a972e8'][x%4]);}else{ctx.fillRect(8*T,0,4*T,15*T);ctx.fillStyle=C.water;ctx.fillRect(1*T,7*T,5*T,2*T);ctx.fillRect(14*T,7*T,5*T,2*T);for(let y=1;y<14;y+=2){flower(7*T,y*T,['#ff5cb8','#ffe76a','#67e7ef'][y%3]);flower(12*T,y*T,['#9c6bea','#ff775e','#fff'][y%3])}}m.blocks.forEach(([x,y,w,h])=>{if(state.scene==='route28'){ctx.fillStyle='#2f7d4b';for(let yy=y;yy<y+h;yy++)for(let xx=x;xx<x+w;xx++){ctx.fillRect(xx*T,yy*T,T,T);ctx.fillStyle='#25683f';ctx.fillRect(xx*T+7,yy*T+5,18,19);ctx.fillStyle='#2f7d4b'}}});}
  function drawHouse(x,y,w,h,roof,label){ctx.fillStyle='#f4d39d';ctx.fillRect(x*T,(y+1)*T,w*T,(h-1)*T);ctx.fillStyle=roof;ctx.fillRect((x-.2)*T,y*T,(w+.4)*T,1.8*T);ctx.fillStyle='#b84072';for(let i=0;i<w;i+=2)ctx.fillRect((x+i)*T,y*T,T,7);ctx.fillStyle='#583848';ctx.fillRect((x+Math.floor(w/2))*T,(y+h-1)*T,T,T);ctx.fillStyle='#fff1b9';ctx.font='bold 11px sans-serif';ctx.textAlign='center';ctx.fillText(label,(x+w/2)*T,(y+2.35)*T)}
  function drawInside(m){for(let y=0;y<H;y++)for(let x=0;x<W;x++)tile(x,y,(x+y)%2?C.floor:'#efc491');ctx.fillStyle=C.wall;m.blocks.forEach(([x,y,w,h])=>ctx.fillRect(x*T,y*T,w*T,h*T));ctx.fillStyle='#f7d85b';ctx.fillRect(8*T,0,4*T,2*T);ctx.fillStyle='#6c405a';ctx.fillRect(10*T,13*T,T,T);ctx.fillStyle='#ad6c72';ctx.fillRect(3*T,4*T,5*T,2*T);ctx.fillStyle='#fff0b5';ctx.fillRect(3.3*T,4.2*T,2*T,1*T);if(state.scene==='slayhouse'){ctx.fillStyle='#f062ad';ctx.fillRect(3*T,3*T,14*T,3*T);ctx.fillStyle='#fff';ctx.font='bold 19px sans-serif';ctx.textAlign='center';ctx.fillText('✦ SLAYHOUSE ✦',10*T,4.7*T)}}
  function drawNpc(n){const px=n.x*T,py=n.y*T;if(n.kind==='sign'){ctx.fillStyle='#72503c';ctx.fillRect(px+14,py+14,5,18);ctx.fillStyle='#f0d59a';ctx.fillRect(px+4,py+2,24,17);return}if(['sexyflex','nocturnyx','veloursa'].includes(n.kind)){drawSlay(px,py,n.kind);return}ctx.fillStyle=portraitColor(n.kind);ctx.fillRect(px+7,py+9,18,21);ctx.fillStyle='#f5c8a7';ctx.fillRect(px+10,py+2,12,11);ctx.fillStyle=n.kind==='mritto'?'#252034':n.kind==='frat'?'#eeebf0':'#713f58';ctx.fillRect(px+8,py,16,6);if(n.kind==='frat'){ctx.fillStyle='#ff75c5';ctx.fillRect(px+4,py+14,5,15);ctx.fillRect(px+23,py+14,5,15)}}
  function drawSlay(px,py,k){if(k==='sexyflex'){ctx.fillStyle='#e6683d';ctx.fillRect(px+2,py+10,28,19);ctx.fillStyle='#f6c65b';ctx.fillRect(px+9,py+4,14,14);ctx.fillStyle='#762d3d';ctx.fillRect(px,py+12,7,9);ctx.fillRect(px+25,py+12,7,9);ctx.fillStyle='#201832';ctx.fillRect(px+12,py+9,3,3);ctx.fillRect(px+19,py+9,3,3)}else{ctx.fillStyle=k==='nocturnyx'?'#302b55':'#e97eb6';ctx.fillRect(px+6,py+8,20,20);ctx.fillRect(px+2,py+12,8,13);ctx.fillRect(px+22,py+12,8,13);ctx.fillStyle=k==='nocturnyx'?'#70e0d3':'#fff0bf';ctx.fillRect(px+10,py+13,4,4);ctx.fillRect(px+19,py+13,4,4);if(k==='veloursa'){ctx.fillStyle='#fff0bf';ctx.fillRect(px+12,py+2,8,8)}}}
  function drawPlayer(){const px=state.x*T,py=state.y*T;ctx.fillStyle='#5c284a';ctx.fillRect(px+8,py+1,16,10);ctx.fillStyle='#efb28e';ctx.fillRect(px+10,py+7,12,9);ctx.fillStyle='#3b315f';ctx.fillRect(px+7,py+15,18,13);ctx.fillStyle='#ffdc4d';ctx.fillRect(px+7,py+17,18,4);ctx.fillStyle='#201832';ctx.fillRect(px+8,py+28,6,4);ctx.fillRect(px+18,py+28,6,4)}
  const handled=new Set(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','z','q','s','d','w','a','e','Enter']);
  addEventListener('keydown',e=>{if(handled.has(e.key.toLowerCase())||handled.has(e.key))e.preventDefault();if(e.repeat)return;const k=e.key.toLowerCase();if(k===' '||k==='e'||k==='enter'){interact();return}if(k==='arrowup'||k==='z'||k==='w')move(0,-1,'up');if(k==='arrowdown'||k==='s')move(0,1,'down');if(k==='arrowleft'||k==='q'||k==='a')move(-1,0,'left');if(k==='arrowright'||k==='d')move(1,0,'right')});
  document.querySelectorAll('[data-key]').forEach(b=>b.addEventListener('pointerdown',()=>{const k=b.dataset.key;if(k==='ArrowUp')move(0,-1,'up');if(k==='ArrowDown')move(0,1,'down');if(k==='ArrowLeft')move(-1,0,'left');if(k==='ArrowRight')move(1,0,'right')}));document.querySelector('[data-action]').addEventListener('pointerdown',interact);
  UI.start.addEventListener('click',()=>{const chosen=document.querySelector('#playerName').value.trim();state.playerName=chosen||'Bulbo';state.started=true;UI.title.hidden=true;showLabel('MAISON DE '+state.playerName.toUpperCase());draw()});UI.mapButton.addEventListener('click',()=>{if(!state.dialogue)UI.map.hidden=false});UI.closeMap.addEventListener('click',()=>UI.map.hidden=true);UI.map.addEventListener('click',e=>{if(e.target===UI.map)UI.map.hidden=true});document.querySelector('#resetButton').addEventListener('click',()=>location.reload());
  draw();
})();

